namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentCode { get; set; } = string.Empty;
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics including statistics and analysis." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Code = "ENG", Name = "English", Description = "Literature, writing, and language studies." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and civilizations." },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, CourseCode = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Covers variables, control structures, functions, and object-oriented basics.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and education. She specializes in programming languages and compilers.", DepartmentId = 1, DepartmentCode = "CS", DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 2, CourseCode = "CS201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park is a researcher in algorithm design with publications in top-tier conferences. He received his PhD from MIT.", DepartmentId = 1, DepartmentCode = "CS", DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 3, CourseCode = "CS301", Title = "Database Systems", Description = "Relational database design, SQL, transaction processing, and modern database technologies.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Prof. Maria Garcia", InstructorBio = "Prof. Garcia worked at Oracle for 10 years before joining academia. She focuses on distributed database systems.", DepartmentId = 1, DepartmentCode = "CS", DepartmentName = "Computer Science", IsFeatured = false },
            new() { Id = 4, CourseCode = "CS401", Title = "Machine Learning", Description = "Introduction to machine learning algorithms, neural networks, and practical applications in data science.", Credits = 4, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Alex Rivera", InstructorBio = "Dr. Rivera leads the AI research lab and has published over 50 papers on deep learning and natural language processing.", DepartmentId = 1, DepartmentCode = "CS", DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 5, CourseCode = "MATH101", Title = "Calculus I", Description = "Limits, derivatives, integrals, and the fundamental theorem of calculus.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator with a passion for making calculus accessible to all students.", DepartmentId = 2, DepartmentCode = "MATH", DepartmentName = "Mathematics", IsFeatured = true },
            new() { Id = 6, CourseCode = "MATH201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson's research focuses on numerical linear algebra and its applications in engineering.", DepartmentId = 2, DepartmentCode = "MATH", DepartmentName = "Mathematics", IsFeatured = false },
            new() { Id = 7, CourseCode = "MATH301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator with a passion for making calculus accessible to all students.", DepartmentId = 2, DepartmentCode = "MATH", DepartmentName = "Mathematics", IsFeatured = false },
            new() { Id = 8, CourseCode = "PHYS101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:50 PM", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres is an experimental physicist who has worked at CERN and Fermilab.", DepartmentId = 3, DepartmentCode = "PHYS", DepartmentName = "Physics", IsFeatured = false },
            new() { Id = 9, CourseCode = "PHYS201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Lisa Nguyen", InstructorBio = "Dr. Nguyen specializes in photonics and has multiple patents in optical communications technology.", DepartmentId = 3, DepartmentCode = "PHYS", DepartmentName = "Physics", IsFeatured = true },
            new() { Id = 10, CourseCode = "ENG101", Title = "Composition and Rhetoric", Description = "Develop clear, effective writing skills through essays, research papers, and rhetorical analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Prof. David Brooks", InstructorBio = "Prof. Brooks is a published author and has taught writing at the university level for over 20 years.", DepartmentId = 4, DepartmentCode = "ENG", DepartmentName = "English", IsFeatured = false },
            new() { Id = 11, CourseCode = "ENG205", Title = "World Literature", Description = "Survey of major literary works from diverse cultures and historical periods.", Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", InstructorName = "Dr. Aisha Patel", InstructorBio = "Dr. Patel is a comparative literature scholar specializing in postcolonial narratives.", DepartmentId = 4, DepartmentCode = "ENG", DepartmentName = "English", IsFeatured = false },
            new() { Id = 12, CourseCode = "HIST101", Title = "World History to 1500", Description = "Survey of major civilizations, events, and themes in world history from antiquity to 1500 CE.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", InstructorName = "Dr. Thomas Wright", InstructorBio = "Dr. Wright is a medieval historian with extensive fieldwork experience across Europe and the Middle East.", DepartmentId = 5, DepartmentCode = "HIST", DepartmentName = "History", IsFeatured = false },
            new() { Id = 13, CourseCode = "HIST202", Title = "Modern American History", Description = "American history from the Civil War to the present, including social, political, and cultural developments.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", InstructorName = "Dr. Karen Mitchell", InstructorBio = "Dr. Mitchell is a public historian who has consulted for the Smithsonian and National Archives.", DepartmentId = 5, DepartmentCode = "HIST", DepartmentName = "History", IsFeatured = true },
        };
    }

    public List<Department> GetAllDepartments() => _departments;

    public Department? GetDepartmentById(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public Department? GetDepartmentByCode(string code) =>
        _departments.FirstOrDefault(d => d.Code.Equals(code, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourseById(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

